const std::size_t N = velocities.size();
if (N != masses.size() || N == 0) return;

const double kB = 1.380649e-23;
std::mt19937 rng(std::random_device{}());
std::normal_distribution<double> dist(0.0, 1.0);

double totalMass = 0.0;
for (double m : masses) totalMass += m;

std::vector<vec3> vels(N);
vec3 comMomentum(0.0, 0.0, 0.0);

for (std::size_t i = 0; i < N; ++i) {
    const double sigma = std::sqrt(kB * temperature / masses[i]);
    vels[i].x = dist(rng) * sigma;
    vels[i].y = dist(rng) * sigma;
    vels[i].z = dist(rng) * sigma;
    comMomentum += vels[i] * masses[i];
}

const vec3 comVelocity = comMomentum / totalMass;
for (std::size_t i = 0; i < N; ++i) {
    velocities[i] = vels[i] - comVelocity;
}
// END_CODE

